-- Schema do backend atual. Campos de data em texto preservam o contrato do painel.
-- Nao remove tabelas nem dados; nomes historicos sao mantidos apenas para importacao.

CREATE TABLE IF NOT EXISTS "configuracoes" (
  "chave" TEXT PRIMARY KEY,
  "valor" TEXT NOT NULL
);
ALTER TABLE "configuracoes" ADD COLUMN IF NOT EXISTS "chave" TEXT;
ALTER TABLE "configuracoes" ADD COLUMN IF NOT EXISTS "valor" TEXT NOT NULL;

