  "suporte_numero" TEXT NOT NULL,
  "ultimo_pagamento" TEXT,
  "proximo_vencimento" TEXT,
  "observacoes" TEXT,
  "whatsapp_numero" TEXT,
  "whatsapp_status" TEXT NOT NULL DEFAULT 'nao_configurado',
