  "whatsapp_ultimo_qr_em" TEXT,
  "gateway_provider" TEXT,
  "gateway_status" TEXT,
  "gateway_external_reference" TEXT,
  "gateway_checkout_url" TEXT,
  "mercado_preapproval_id" TEXT,
  "mercado_payer_email" TEXT,
  "mercado_next_payment_date" TEXT,
  "mercado_last_payload" TEXT,
  "plano" TEXT NOT NULL DEFAULT 'Plano Profissional',
  "valor_plano" DOUBLE PRECISION NOT NULL DEFAULT 65,
  "status_assinatura" TEXT NOT NULL DEFAULT 'PENDENTE',
  "subscription_id" TEXT,
  "customer_id" TEXT,
  "payment_id" TEXT,
  "dias_atraso" BIGINT NOT NULL DEFAULT 0,
  "bloqueado" BIGINT NOT NULL DEFAULT 0,
  "data_bloqueio" TEXT,
  "trial" BIGINT NOT NULL DEFAULT 0,
