CREATE TABLE IF NOT EXISTS "agendamentos" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "assinatura_id" BIGINT,
  "cliente_id" BIGINT,
  "servico_id" BIGINT,
  "nome_cliente" TEXT,
  "telefone" TEXT,
  "servico_nome" TEXT,
  "preco" DOUBLE PRECISION,
  "data" TEXT,
  "hora" TEXT,
  "status" TEXT,
  "lembrete_15_enviado_em" TEXT,
  "lembrete_7_enviado_em" TEXT,
  FOREIGN KEY ("servico_id") REFERENCES "servicos" ("id") ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY ("cliente_id") REFERENCES "clientes" ("id") ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY ("assinatura_id") REFERENCES "assinaturas" ("id") ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED
);
