CREATE TABLE IF NOT EXISTS "whatsapp_messages" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "assinatura_id" BIGINT NOT NULL,
  "instance" TEXT NOT NULL,
  "phone" TEXT NOT NULL,
  "message_id" TEXT NOT NULL,
  "response" TEXT NOT NULL,
