CREATE UNIQUE INDEX IF NOT EXISTS idx_password_reset_tokens_uniq
          ON password_reset_tokens (assinatura_id)
          WHERE used_at IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS idx_agendamentos_tenant_horario
      ON agendamentos (COALESCE(assinatura_id, 0), data, hora) WHERE status = 'confirmado';
CREATE INDEX IF NOT EXISTS idx_whatsapp_messages_pending ON whatsapp_messages(status, lease_until, id);
CREATE TABLE IF NOT EXISTS sqlite_imports (source_hash TEXT PRIMARY KEY, imported_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, counts JSONB NOT NULL);

CREATE INDEX IF NOT EXISTS idx_clientes_telefone ON clientes(telefone);
